parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "inquiry_summary": {"type": "string", "description": "One sentence: what the customer wants"},
    "retrieved_context": {"type": "string", "description": "The facts that came back from the tools, plain text. Empty if none."},
    "response_draft": {"type": "string", "description": "The reply a human could send as is. Empty when escalating without facts."},
    "next_action": {"type": "string", "enum": ["Approve", "Escalate"]},
    "reason": {"type": "string", "enum": ["standard", "out_of_scope", "missing_argument", "tool_failure", "low_confidence"]},
    "tools_used": {"type": "array", "items": {"type": "string"}, "description": "Tool names called, in order"}
  },
  "required": ["inquiry_summary", "retrieved_context", "response_draft", "next_action", "reason", "tools_used"]
}

parameters.text:
=*{{ $json.next_action }}* on inquiry {{ $json.inquiry_id }} ({{ $json.reason }})
*Summary:* {{ $json.inquiry_summary }}
*What the tools found:* {{ $json.retrieved_context || 'nothing retrieved' }}
*Draft reply:*
{{ $json.response_draft || '(none, escalated)' }}
*Tools used:* {{ $json.tools_used }}

